    wire [0:0] io_64b_b_rarb_pick = (io_64b_b_rarb_rr == 1'd0) ? (io_64b_b_rarb_req[0] ? 1'd0 : 1'd1) : 
        io_64b_b_rarb_req[1] ? 1'd1 : 1'd0;
    wire [0:0] io_64b_b_rarb_gnt = io_64b_b_rarb_locked ? io_64b_b_rarb_lock : io_64b_b_rarb_pick;
    wire io_64b_b_rarb_gnt_valid = io_64b_b_rarb_locked || (|io_64b_b_rarb_req);
    wire io_64b_b_rgnt_mem0 = io_64b_b_rarb_gnt_valid && (io_64b_b_rarb_gnt == 1'd0);
    wire io_64b_b_rgnt_mem3 = io_64b_b_rarb_gnt_valid && (io_64b_b_rarb_gnt == 1'd1);
    wire io_64b_b_rarb_vld = (io_64b_b_rgnt_mem0 && io_64b_b_rarb_req[0]) || (io_64b_b_rgnt_mem3 && io_64b_b_rarb_req[1]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            io_64b_b_rarb_lock   <= '0;
            io_64b_b_rarb_rr     <= '0;
            io_64b_b_rarb_locked <= 1'b0;
        end else if (io_64b_b_rarb_vld && io_64b_bready) begin
            io_64b_b_rarb_locked <= 1'b0;
            io_64b_b_rarb_rr <= (io_64b_b_rarb_gnt == 1'd1) ? 1'd0 : io_64b_b_rarb_gnt + 1'b1;
        end else if (io_64b_b_rarb_vld) begin
            io_64b_b_rarb_lock   <= io_64b_b_rarb_gnt;       // offered, not taken: hold
            io_64b_b_rarb_locked <= 1'b1;
        end
    )

    // ---- R response arbiter, master io 64b: round-robin per beat, lock until taken ----
    logic [1:0] io_64b_r_rarb_req;
    assign io_64b_r_rarb_req = {((mem3_axi_rid_bridge_id == 3) && mem3_axi_rid_valid) && mem3_axi_rvalid, ((mem0_axi_rid_bridge_id == 3) && mem0_axi_rid_valid) && mem0_axi_rvalid};
    logic [0:0] io_64b_r_rarb_lock, io_64b_r_rarb_rr;
    logic io_64b_r_rarb_locked;
    wire [0:0] io_64b_r_rarb_pick = (io_64b_r_rarb_rr == 1'd0) ? (io_64b_r_rarb_req[0] ? 1'd0 : 1'd1) : 
        io_64b_r_rarb_req[1] ? 1'd1 : 1'd0;
    wire [0:0] io_64b_r_rarb_gnt = io_64b_r_rarb_locked ? io_64b_r_rarb_lock : io_64b_r_rarb_pick;
    wire io_64b_r_rarb_gnt_valid = io_64b_r_rarb_locked || (|io_64b_r_rarb_req);
    wire io_64b_r_rgnt_mem0 = io_64b_r_rarb_gnt_valid && (io_64b_r_rarb_gnt == 1'd0);
    wire io_64b_r_rgnt_mem3 = io_64b_r_rarb_gnt_valid && (io_64b_r_rarb_gnt == 1'd1);
    wire io_64b_r_rarb_vld = (io_64b_r_rgnt_mem0 && io_64b_r_rarb_req[0]) || (io_64b_r_rgnt_mem3 && io_64b_r_rarb_req[1]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            io_64b_r_rarb_lock   <= '0;
            io_64b_r_rarb_rr     <= '0;
            io_64b_r_rarb_locked <= 1'b0;
        end else if (io_64b_r_rarb_vld && io_64b_rready) begin
            io_64b_r_rarb_locked <= 1'b0;
            io_64b_r_rarb_rr <= (io_64b_r_rarb_gnt == 1'd1) ? 1'd0 : io_64b_r_rarb_gnt + 1'b1;
        end else if (io_64b_r_rarb_vld) begin
            io_64b_r_rarb_lock   <= io_64b_r_rarb_gnt;       // offered, not taken: hold
            io_64b_r_rarb_locked <= 1'b1;
        end
    )

    // ---- B response arbiter, master io 128b: round-robin per beat, lock until taken ----
    logic [1:0] io_128b_b_rarb_req;
    assign io_128b_b_rarb_req = {((subtractive_axi_bid_bridge_id == 3) && subtractive_axi_bid_valid) && subtractive_axi_bvalid, ((mem1_axi_bid_bridge_id == 3) && mem1_axi_bid_valid) && mem1_axi_bvalid};
    logic [0:0] io_128b_b_rarb_lock, io_128b_b_rarb_rr;
    logic io_128b_b_rarb_locked;
    wire [0:0] io_128b_b_rarb_pick = (io_128b_b_rarb_rr == 1'd0) ? (io_128b_b_rarb_req[0] ? 1'd0 : 1'd1) : 
        io_128b_b_rarb_req[1] ? 1'd1 : 1'd0;
    wire [0:0] io_128b_b_rarb_gnt = io_128b_b_rarb_locked ? io_128b_b_rarb_lock : io_128b_b_rarb_pick;
    wire io_128b_b_rarb_gnt_valid = io_128b_b_rarb_locked || (|io_128b_b_rarb_req);
    wire io_128b_b_rgnt_mem1 = io_128b_b_rarb_gnt_valid && (io_128b_b_rarb_gnt == 1'd0);
    wire io_128b_b_rgnt_subtractive = io_128b_b_rarb_gnt_valid && (io_128b_b_rarb_gnt == 1'd1);
    wire io_128b_b_rarb_vld = (io_128b_b_rgnt_mem1 && io_128b_b_rarb_req[0]) || (io_128b_b_rgnt_subtractive && io_128b_b_rarb_req[1]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            io_128b_b_rarb_lock   <= '0;
            io_128b_b_rarb_rr     <= '0;
            io_128b_b_rarb_locked <= 1'b0;
        end else if (io_128b_b_rarb_vld && io_128b_bready) begin
            io_128b_b_rarb_locked <= 1'b0;
            io_128b_b_rarb_rr <= (io_128b_b_rarb_gnt == 1'd1) ? 1'd0 : io_128b_b_rarb_gnt + 1'b1;
        end else if (io_128b_b_rarb_vld) begin
            io_128b_b_rarb_lock   <= io_128b_b_rarb_gnt;       // offered, not taken: hold
            io_128b_b_rarb_locked <= 1'b1;
        end
    )

    // ---- R response arbiter, master io 128b: round-robin per beat, lock until taken ----
    logic [1:0] io_128b_r_rarb_req;
    assign io_128b_r_rarb_req = {((subtractive_axi_rid_bridge_id == 3) && subtractive_axi_rid_valid) && subtractive_axi_rvalid, ((mem1_axi_rid_bridge_id == 3) && mem1_axi_rid_valid) && mem1_axi_rvalid};
    logic [0:0] io_128b_r_rarb_lock, io_128b_r_rarb_rr;
    logic io_128b_r_rarb_locked;
    wire [0:0] io_128b_r_rarb_pick = (io_128b_r_rarb_rr == 1'd0) ? (io_128b_r_rarb_req[0] ? 1'd0 : 1'd1) : 
        io_128b_r_rarb_req[1] ? 1'd1 : 1'd0;
    wire [0:0] io_128b_r_rarb_gnt = io_128b_r_rarb_locked ? io_128b_r_rarb_lock : io_128b_r_rarb_pick;
    wire io_128b_r_rarb_gnt_valid = io_128b_r_rarb_locked || (|io_128b_r_rarb_req);
    wire io_128b_r_rgnt_mem1 = io_128b_r_rarb_gnt_valid && (io_128b_r_rarb_gnt == 1'd0);
    wire io_128b_r_rgnt_subtractive = io_128b_r_rarb_gnt_valid && (io_128b_r_rarb_gnt == 1'd1);
    wire io_128b_r_rarb_vld = (io_128b_r_rgnt_mem1 && io_128b_r_rarb_req[0]) || (io_128b_r_rgnt_subtractive && io_128b_r_rarb_req[1]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            io_128b_r_rarb_lock   <= '0;
            io_128b_r_rarb_rr     <= '0;
            io_128b_r_rarb_locked <= 1'b0;
        end else if (io_128b_r_rarb_vld && io_128b_rready) begin
            io_128b_r_rarb_locked <= 1'b0;
            io_128b_r_rarb_rr <= (io_128b_r_rarb_gnt == 1'd1) ? 1'd0 : io_128b_r_rarb_gnt + 1'b1;
        end else if (io_128b_r_rarb_vld) begin
            io_128b_r_rarb_lock   <= io_128b_r_rarb_gnt;       // offered, not taken: hold
            io_128b_r_rarb_locked <= 1'b1;
        end
    )

    // ================================================================
    // Slave 0: mem0 (64b)
    // ================================================================
    // Multi-master (4 masters) → mem0
    //   - cpu (rw)
    //   - dma (rw)
    //   - acc (rw)
    //   - io (rw)

    wire cpu_64b_aw_to_mem0 = (cpu_64b_aw.addr <= 32'h0fffffff);
    wire cpu_64b_ar_to_mem0 = (cpu_64b_ar.addr <= 32'h0fffffff);
    wire dma_64b_aw_to_mem0 = (dma_64b_aw.addr <= 32'h0fffffff);
    wire dma_64b_ar_to_mem0 = (dma_64b_ar.addr <= 32'h0fffffff);
    wire acc_64b_aw_to_mem0 = (acc_64b_aw.addr <= 32'h0fffffff);
    wire acc_64b_ar_to_mem0 = (acc_64b_ar.addr <= 32'h0fffffff);
    wire io_64b_aw_to_mem0 = (io_64b_aw.addr <= 32'h0fffffff);
    wire io_64b_ar_to_mem0 = (io_64b_ar.addr <= 32'h0fffffff);

    // AW request slots for mem0: arbitration at the slave pins
    assign cpu_64b_aw_slot_mem0_in_valid = cpu_64b_aw_to_mem0 && cpu_64b_awvalid && !cpu_64b_aw_hold_mem0;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_64b_aw_slot_mem0 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_64b_aw_slot_mem0_in_valid), .wr_ready(cpu_64b_aw_slot_mem0_in_ready), .wr_data(cpu_64b_aw),
        .rd_valid(cpu_64b_aw_slot_mem0_valid), .rd_ready(cpu_64b_aw_slot_mem0_ready), .rd_data(cpu_64b_aw_slot_mem0),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign dma_64b_aw_slot_mem0_in_valid = dma_64b_aw_to_mem0 && dma_64b_awvalid && !dma_64b_aw_hold_mem0;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_dma_64b_aw_slot_mem0 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_64b_aw_slot_mem0_in_valid), .wr_ready(dma_64b_aw_slot_mem0_in_ready), .wr_data(dma_64b_aw),
        .rd_valid(dma_64b_aw_slot_mem0_valid), .rd_ready(dma_64b_aw_slot_mem0_ready), .rd_data(dma_64b_aw_slot_mem0),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_64b_aw_slot_mem0_in_valid = acc_64b_aw_to_mem0 && acc_64b_awvalid && !acc_64b_aw_hold_mem0;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_acc_64b_aw_slot_mem0 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_64b_aw_slot_mem0_in_valid), .wr_ready(acc_64b_aw_slot_mem0_in_ready), .wr_data(acc_64b_aw),
        .rd_valid(acc_64b_aw_slot_mem0_valid), .rd_ready(acc_64b_aw_slot_mem0_ready), .rd_data(acc_64b_aw_slot_mem0),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_64b_aw_slot_mem0_in_valid = io_64b_aw_to_mem0 && io_64b_awvalid && !io_64b_aw_hold_mem0;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_io_64b_aw_slot_mem0 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_64b_aw_slot_mem0_in_valid), .wr_ready(io_64b_aw_slot_mem0_in_ready), .wr_data(io_64b_aw),
        .rd_valid(io_64b_aw_slot_mem0_valid), .rd_ready(io_64b_aw_slot_mem0_ready), .rd_data(io_64b_aw_slot_mem0),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for mem0: round-robin, lock until handshake ----
    logic [3:0] mem0_aw_arb_req;
    assign mem0_aw_arb_req = {io_64b_aw_slot_mem0_valid, acc_64b_aw_slot_mem0_valid, dma_64b_aw_slot_mem0_valid, cpu_64b_aw_slot_mem0_valid};
    logic [1:0] mem0_aw_arb_lock, mem0_aw_arb_rr;
    logic mem0_aw_arb_locked;
    wire [1:0] mem0_aw_arb_pick = (mem0_aw_arb_rr == 2'd0) ? (mem0_aw_arb_req[0] ? 2'd0 : mem0_aw_arb_req[1] ? 2'd1 : mem0_aw_arb_req[2] ? 2'd2 : 2'd3) : 
        (mem0_aw_arb_rr == 2'd1) ? (mem0_aw_arb_req[1] ? 2'd1 : mem0_aw_arb_req[2] ? 2'd2 : mem0_aw_arb_req[3] ? 2'd3 : 2'd0) : 
        (mem0_aw_arb_rr == 2'd2) ? (mem0_aw_arb_req[2] ? 2'd2 : mem0_aw_arb_req[3] ? 2'd3 : mem0_aw_arb_req[0] ? 2'd0 : 2'd1) : 
        mem0_aw_arb_req[3] ? 2'd3 : mem0_aw_arb_req[0] ? 2'd0 : mem0_aw_arb_req[1] ? 2'd1 : 2'd2;
    wire mem0_aw_arb_gnt_valid = mem0_aw_arb_locked || (|mem0_aw_arb_req);
    wire [1:0] mem0_aw_arb_gnt = mem0_aw_arb_locked ? mem0_aw_arb_lock : mem0_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem0_aw_arb_lock   <= '0;
            mem0_aw_arb_rr     <= '0;
            mem0_aw_arb_locked <= 1'b0;
        end else begin
            if (mem0_axi_awvalid && mem0_axi_awready) begin
                mem0_aw_arb_locked <= 1'b0;
                mem0_aw_arb_rr <= (mem0_aw_arb_gnt == 2'd3) ? 2'd0 : mem0_aw_arb_gnt + 1'b1;
            end else if (mem0_axi_awvalid) begin
                mem0_aw_arb_lock   <= mem0_aw_arb_gnt;
                mem0_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_64b_aw_gnt_mem0 = mem0_aw_arb_gnt_valid && (mem0_aw_arb_gnt == 2'd0) && mem0_aw_arb_req[0];
    wire dma_64b_aw_gnt_mem0 = mem0_aw_arb_gnt_valid && (mem0_aw_arb_gnt == 2'd1) && mem0_aw_arb_req[1];
    wire acc_64b_aw_gnt_mem0 = mem0_aw_arb_gnt_valid && (mem0_aw_arb_gnt == 2'd2) && mem0_aw_arb_req[2];
    wire io_64b_aw_gnt_mem0 = mem0_aw_arb_gnt_valid && (mem0_aw_arb_gnt == 2'd3) && mem0_aw_arb_req[3];
    assign cpu_64b_aw_slot_mem0_ready = cpu_64b_aw_gnt_mem0 && mem0_axi_awready;
    assign dma_64b_aw_slot_mem0_ready = dma_64b_aw_gnt_mem0 && mem0_axi_awready;
    assign acc_64b_aw_slot_mem0_ready = acc_64b_aw_gnt_mem0 && mem0_axi_awready;
    assign io_64b_aw_slot_mem0_ready = io_64b_aw_gnt_mem0 && mem0_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign mem0_axi_awid = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.id : '0) |
        (dma_64b_aw_gnt_mem0 ? dma_64b_aw_slot_mem0.id : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.id : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.id : '0);
    assign mem0_axi_awaddr = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.addr : '0) |
        (dma_64b_aw_gnt_mem0 ? dma_64b_aw_slot_mem0.addr : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.addr : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.addr : '0);
    assign mem0_axi_awlen = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.len : '0) |
        (dma_64b_aw_gnt_mem0 ? dma_64b_aw_slot_mem0.len : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.len : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.len : '0);
    assign mem0_axi_awsize = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.size : '0) |
        (dma_64b_aw_gnt_mem0 ? dma_64b_aw_slot_mem0.size : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.size : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.size : '0);
    assign mem0_axi_awburst = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.burst : '0) |
        (dma_64b_aw_gnt_mem0 ? dma_64b_aw_slot_mem0.burst : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.burst : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.burst : '0);
    assign mem0_axi_awlock = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.lock : '0) |
        (dma_64b_aw_gnt_mem0 ? dma_64b_aw_slot_mem0.lock : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.lock : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.lock : '0);
    assign mem0_axi_awcache = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.cache : '0) |
        (dma_64b_aw_gnt_mem0 ? dma_64b_aw_slot_mem0.cache : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.cache : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.cache : '0);
    assign mem0_axi_awprot = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.prot : '0) |
        (dma_64b_aw_gnt_mem0 ? dma_64b_aw_slot_mem0.prot : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.prot : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.prot : '0);
    assign mem0_axi_awqos = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.qos : '0) |
        (dma_64b_aw_gnt_mem0 ? dma_64b_aw_slot_mem0.qos : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.qos : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.qos : '0);
    assign mem0_axi_awregion = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.region : '0) |
        (dma_64b_aw_gnt_mem0 ? dma_64b_aw_slot_mem0.region : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.region : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.region : '0);
    assign mem0_axi_awuser = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.user : '0) |
        (dma_64b_aw_gnt_mem0 ? dma_64b_aw_slot_mem0.user : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.user : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.user : '0);
    assign mem0_axi_awvalid = cpu_64b_aw_gnt_mem0 || dma_64b_aw_gnt_mem0 || acc_64b_aw_gnt_mem0 || io_64b_aw_gnt_mem0;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [1:0] mem0_wowner_mem [16];
    logic [4:0] mem0_wowner_wptr, mem0_wowner_rptr;
    logic mem0_wowner_ahead;
    wire mem0_wowner_valid = (mem0_wowner_wptr != mem0_wowner_rptr);
    wire mem0_wowner_byp = !mem0_wowner_valid && !mem0_wowner_ahead && mem0_axi_awvalid;
    wire mem0_wowner_aw_hs = mem0_axi_awvalid && mem0_axi_awready;
    wire mem0_wowner_w_end = mem0_axi_wvalid && mem0_axi_wready && mem0_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem0_wowner_wptr  <= '0;
            mem0_wowner_rptr  <= '0;
            mem0_wowner_ahead <= 1'b0;
        end else begin
            if (mem0_wowner_aw_hs && mem0_wowner_ahead) begin
                mem0_wowner_ahead <= 1'b0;   // its W already went
            end else if (mem0_wowner_aw_hs && !(mem0_wowner_byp && mem0_wowner_w_end)) begin
                mem0_wowner_mem[mem0_wowner_wptr[3:0]] <= mem0_aw_arb_gnt;
                mem0_wowner_wptr <= mem0_wowner_wptr + 1'b1;
            end else if (!mem0_wowner_aw_hs && mem0_wowner_byp && mem0_wowner_w_end) begin
                mem0_wowner_ahead <= 1'b1;
            end
            if (mem0_wowner_valid && mem0_wowner_w_end) begin
