        end
    )
    wire cpu_128b_aw_gnt_mem1 = mem1_aw_arb_gnt_valid && (mem1_aw_arb_gnt == 2'd0) && mem1_aw_arb_req[0];
    wire dma_128b_aw_gnt_mem1 = mem1_aw_arb_gnt_valid && (mem1_aw_arb_gnt == 2'd1) && mem1_aw_arb_req[1];
    wire acc_128b_aw_gnt_mem1 = mem1_aw_arb_gnt_valid && (mem1_aw_arb_gnt == 2'd2) && mem1_aw_arb_req[2];
    wire io_128b_aw_gnt_mem1 = mem1_aw_arb_gnt_valid && (mem1_aw_arb_gnt == 2'd3) && mem1_aw_arb_req[3];
    assign cpu_128b_aw_slot_mem1_ready = cpu_128b_aw_gnt_mem1 && mem1_axi_awready;
    assign dma_128b_aw_slot_mem1_ready = dma_128b_aw_gnt_mem1 && mem1_axi_awready;
    assign acc_128b_aw_slot_mem1_ready = acc_128b_aw_gnt_mem1 && mem1_axi_awready;
    assign io_128b_aw_slot_mem1_ready = io_128b_aw_gnt_mem1 && mem1_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign mem1_axi_awid = (cpu_128b_aw_gnt_mem1 ? cpu_128b_aw_slot_mem1.id : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.id : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.id : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.id : '0);
    assign mem1_axi_awaddr = (cpu_128b_aw_gnt_mem1 ? cpu_128b_aw_slot_mem1.addr : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.addr : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.addr : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.addr : '0);
    assign mem1_axi_awlen = (cpu_128b_aw_gnt_mem1 ? cpu_128b_aw_slot_mem1.len : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.len : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.len : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.len : '0);
    assign mem1_axi_awsize = (cpu_128b_aw_gnt_mem1 ? cpu_128b_aw_slot_mem1.size : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.size : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.size : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.size : '0);
    assign mem1_axi_awburst = (cpu_128b_aw_gnt_mem1 ? cpu_128b_aw_slot_mem1.burst : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.burst : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.burst : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.burst : '0);
    assign mem1_axi_awlock = (cpu_128b_aw_gnt_mem1 ? cpu_128b_aw_slot_mem1.lock : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.lock : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.lock : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.lock : '0);
    assign mem1_axi_awcache = (cpu_128b_aw_gnt_mem1 ? cpu_128b_aw_slot_mem1.cache : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.cache : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.cache : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.cache : '0);
    assign mem1_axi_awprot = (cpu_128b_aw_gnt_mem1 ? cpu_128b_aw_slot_mem1.prot : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.prot : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.prot : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.prot : '0);
    assign mem1_axi_awqos = (cpu_128b_aw_gnt_mem1 ? cpu_128b_aw_slot_mem1.qos : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.qos : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.qos : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.qos : '0);
    assign mem1_axi_awregion = (cpu_128b_aw_gnt_mem1 ? cpu_128b_aw_slot_mem1.region : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.region : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.region : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.region : '0);
    assign mem1_axi_awuser = (cpu_128b_aw_gnt_mem1 ? cpu_128b_aw_slot_mem1.user : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.user : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.user : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.user : '0);
    assign mem1_axi_awvalid = cpu_128b_aw_gnt_mem1 || dma_128b_aw_gnt_mem1 || acc_128b_aw_gnt_mem1 || io_128b_aw_gnt_mem1;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [1:0] mem1_wowner_mem [16];
    logic [4:0] mem1_wowner_wptr, mem1_wowner_rptr;
    logic mem1_wowner_ahead;
    wire mem1_wowner_valid = (mem1_wowner_wptr != mem1_wowner_rptr);
    wire mem1_wowner_byp = !mem1_wowner_valid && !mem1_wowner_ahead && mem1_axi_awvalid;
    wire mem1_wowner_aw_hs = mem1_axi_awvalid && mem1_axi_awready;
    wire mem1_wowner_w_end = mem1_axi_wvalid && mem1_axi_wready && mem1_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem1_wowner_wptr  <= '0;
            mem1_wowner_rptr  <= '0;
            mem1_wowner_ahead <= 1'b0;
        end else begin
            if (mem1_wowner_aw_hs && mem1_wowner_ahead) begin
                mem1_wowner_ahead <= 1'b0;   // its W already went
            end else if (mem1_wowner_aw_hs && !(mem1_wowner_byp && mem1_wowner_w_end)) begin
                mem1_wowner_mem[mem1_wowner_wptr[3:0]] <= mem1_aw_arb_gnt;
                mem1_wowner_wptr <= mem1_wowner_wptr + 1'b1;
            end else if (!mem1_wowner_aw_hs && mem1_wowner_byp && mem1_wowner_w_end) begin
                mem1_wowner_ahead <= 1'b1;
            end
            if (mem1_wowner_valid && mem1_wowner_w_end) begin
                mem1_wowner_rptr <= mem1_wowner_rptr + 1'b1;
            end
        end
    )
    wire [1:0] mem1_wowner_head = mem1_wowner_valid ? mem1_wowner_mem[mem1_wowner_rptr[3:0]]
                                       : mem1_aw_arb_gnt;
    assign cpu_128b_w_sel_mem1 = (mem1_wowner_valid || mem1_wowner_byp) && (mem1_wowner_head == 2'd0) && cpu_128b_w_to_mem1;
    assign dma_128b_w_sel_mem1 = (mem1_wowner_valid || mem1_wowner_byp) && (mem1_wowner_head == 2'd1) && dma_128b_w_to_mem1;
    assign acc_128b_w_sel_mem1 = (mem1_wowner_valid || mem1_wowner_byp) && (mem1_wowner_head == 2'd2) && acc_128b_w_to_mem1;
    assign io_128b_w_sel_mem1 = (mem1_wowner_valid || mem1_wowner_byp) && (mem1_wowner_head == 2'd3) && io_128b_w_to_mem1;

    // W channel (owner-gated mux across writing masters)
    assign mem1_axi_wdata = ((cpu_128b_w_sel_mem1 && cpu_128b_wvalid) ? cpu_128b_w.data : '0) |
        ((dma_128b_w_sel_mem1 && dma_128b_wvalid) ? dma_128b_w.data : '0) |
        ((acc_128b_w_sel_mem1 && acc_128b_wvalid) ? acc_128b_w.data : '0) |
        ((io_128b_w_sel_mem1 && io_128b_wvalid) ? io_128b_w.data : '0);
    assign mem1_axi_wstrb = ((cpu_128b_w_sel_mem1 && cpu_128b_wvalid) ? cpu_128b_w.strb : '0) |
        ((dma_128b_w_sel_mem1 && dma_128b_wvalid) ? dma_128b_w.strb : '0) |
        ((acc_128b_w_sel_mem1 && acc_128b_wvalid) ? acc_128b_w.strb : '0) |
        ((io_128b_w_sel_mem1 && io_128b_wvalid) ? io_128b_w.strb : '0);
    assign mem1_axi_wlast = ((cpu_128b_w_sel_mem1 && cpu_128b_wvalid) ? cpu_128b_w.last : '0) |
        ((dma_128b_w_sel_mem1 && dma_128b_wvalid) ? dma_128b_w.last : '0) |
        ((acc_128b_w_sel_mem1 && acc_128b_wvalid) ? acc_128b_w.last : '0) |
        ((io_128b_w_sel_mem1 && io_128b_wvalid) ? io_128b_w.last : '0);
    assign mem1_axi_wuser = ((cpu_128b_w_sel_mem1 && cpu_128b_wvalid) ? cpu_128b_w.user : '0) |
        ((dma_128b_w_sel_mem1 && dma_128b_wvalid) ? dma_128b_w.user : '0) |
        ((acc_128b_w_sel_mem1 && acc_128b_wvalid) ? acc_128b_w.user : '0) |
        ((io_128b_w_sel_mem1 && io_128b_wvalid) ? io_128b_w.user : '0);
    assign mem1_axi_wvalid = (cpu_128b_w_sel_mem1 && cpu_128b_wvalid) || (dma_128b_w_sel_mem1 && dma_128b_wvalid) || (acc_128b_w_sel_mem1 && acc_128b_wvalid) || (io_128b_w_sel_mem1 && io_128b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign mem1_axi_bready = (cpu_128b_b_rgnt_mem1 ? cpu_128b_bready : '0) |
        (dma_128b_b_rgnt_mem1 ? dma_128b_bready : '0) |
        (acc_128b_b_rgnt_mem1 ? acc_128b_bready : '0) |
        (io_128b_b_rgnt_mem1 ? io_128b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign mem1_axi_bridge_id_aw = (cpu_128b_aw_gnt_mem1 ? cpu_bridge_id_aw : '0) |
        (dma_128b_aw_gnt_mem1 ? dma_bridge_id_aw : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_bridge_id_aw : '0) |
        (io_128b_aw_gnt_mem1 ? io_bridge_id_aw : '0);

    // AR request slots for mem1: arbitration at the slave pins
    assign cpu_128b_ar_slot_mem1_in_valid = cpu_128b_ar_to_mem1 && cpu_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_128b_ar_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_128b_ar_slot_mem1_in_valid), .wr_ready(cpu_128b_ar_slot_mem1_in_ready), .wr_data(cpu_128b_ar),
        .rd_valid(cpu_128b_ar_slot_mem1_valid), .rd_ready(cpu_128b_ar_slot_mem1_ready), .rd_data(cpu_128b_ar_slot_mem1),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign dma_128b_ar_slot_mem1_in_valid = dma_128b_ar_to_mem1 && dma_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_dma_128b_ar_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_128b_ar_slot_mem1_in_valid), .wr_ready(dma_128b_ar_slot_mem1_in_ready), .wr_data(dma_128b_ar),
        .rd_valid(dma_128b_ar_slot_mem1_valid), .rd_ready(dma_128b_ar_slot_mem1_ready), .rd_data(dma_128b_ar_slot_mem1),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_128b_ar_slot_mem1_in_valid = acc_128b_ar_to_mem1 && acc_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_acc_128b_ar_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_128b_ar_slot_mem1_in_valid), .wr_ready(acc_128b_ar_slot_mem1_in_ready), .wr_data(acc_128b_ar),
        .rd_valid(acc_128b_ar_slot_mem1_valid), .rd_ready(acc_128b_ar_slot_mem1_ready), .rd_data(acc_128b_ar_slot_mem1),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_128b_ar_slot_mem1_in_valid = io_128b_ar_to_mem1 && io_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_io_128b_ar_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_128b_ar_slot_mem1_in_valid), .wr_ready(io_128b_ar_slot_mem1_in_ready), .wr_data(io_128b_ar),
        .rd_valid(io_128b_ar_slot_mem1_valid), .rd_ready(io_128b_ar_slot_mem1_ready), .rd_data(io_128b_ar_slot_mem1),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for mem1: round-robin, lock until handshake ----
    logic [3:0] mem1_ar_arb_req;
    assign mem1_ar_arb_req = {io_128b_ar_slot_mem1_valid, acc_128b_ar_slot_mem1_valid, dma_128b_ar_slot_mem1_valid, cpu_128b_ar_slot_mem1_valid};
    logic [1:0] mem1_ar_arb_lock, mem1_ar_arb_rr;
    logic mem1_ar_arb_locked;
    wire [1:0] mem1_ar_arb_pick = (mem1_ar_arb_rr == 2'd0) ? (mem1_ar_arb_req[0] ? 2'd0 : mem1_ar_arb_req[1] ? 2'd1 : mem1_ar_arb_req[2] ? 2'd2 : 2'd3) : 
        (mem1_ar_arb_rr == 2'd1) ? (mem1_ar_arb_req[1] ? 2'd1 : mem1_ar_arb_req[2] ? 2'd2 : mem1_ar_arb_req[3] ? 2'd3 : 2'd0) : 
        (mem1_ar_arb_rr == 2'd2) ? (mem1_ar_arb_req[2] ? 2'd2 : mem1_ar_arb_req[3] ? 2'd3 : mem1_ar_arb_req[0] ? 2'd0 : 2'd1) : 
        mem1_ar_arb_req[3] ? 2'd3 : mem1_ar_arb_req[0] ? 2'd0 : mem1_ar_arb_req[1] ? 2'd1 : 2'd2;
    wire mem1_ar_arb_gnt_valid = mem1_ar_arb_locked || (|mem1_ar_arb_req);
    wire [1:0] mem1_ar_arb_gnt = mem1_ar_arb_locked ? mem1_ar_arb_lock : mem1_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem1_ar_arb_lock   <= '0;
            mem1_ar_arb_rr     <= '0;
            mem1_ar_arb_locked <= 1'b0;
        end else begin
            if (mem1_axi_arvalid && mem1_axi_arready) begin
                mem1_ar_arb_locked <= 1'b0;
                mem1_ar_arb_rr <= (mem1_ar_arb_gnt == 2'd3) ? 2'd0 : mem1_ar_arb_gnt + 1'b1;
            end else if (mem1_axi_arvalid) begin
                mem1_ar_arb_lock   <= mem1_ar_arb_gnt;
                mem1_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_128b_ar_gnt_mem1 = mem1_ar_arb_gnt_valid && (mem1_ar_arb_gnt == 2'd0) && mem1_ar_arb_req[0];
    wire dma_128b_ar_gnt_mem1 = mem1_ar_arb_gnt_valid && (mem1_ar_arb_gnt == 2'd1) && mem1_ar_arb_req[1];
    wire acc_128b_ar_gnt_mem1 = mem1_ar_arb_gnt_valid && (mem1_ar_arb_gnt == 2'd2) && mem1_ar_arb_req[2];
    wire io_128b_ar_gnt_mem1 = mem1_ar_arb_gnt_valid && (mem1_ar_arb_gnt == 2'd3) && mem1_ar_arb_req[3];
    assign cpu_128b_ar_slot_mem1_ready = cpu_128b_ar_gnt_mem1 && mem1_axi_arready;
    assign dma_128b_ar_slot_mem1_ready = dma_128b_ar_gnt_mem1 && mem1_axi_arready;
    assign acc_128b_ar_slot_mem1_ready = acc_128b_ar_gnt_mem1 && mem1_axi_arready;
    assign io_128b_ar_slot_mem1_ready = io_128b_ar_gnt_mem1 && mem1_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign mem1_axi_arid = (cpu_128b_ar_gnt_mem1 ? cpu_128b_ar_slot_mem1.id : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.id : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.id : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.id : '0);
    assign mem1_axi_araddr = (cpu_128b_ar_gnt_mem1 ? cpu_128b_ar_slot_mem1.addr : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.addr : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.addr : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.addr : '0);
    assign mem1_axi_arlen = (cpu_128b_ar_gnt_mem1 ? cpu_128b_ar_slot_mem1.len : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.len : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.len : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.len : '0);
    assign mem1_axi_arsize = (cpu_128b_ar_gnt_mem1 ? cpu_128b_ar_slot_mem1.size : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.size : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.size : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.size : '0);
    assign mem1_axi_arburst = (cpu_128b_ar_gnt_mem1 ? cpu_128b_ar_slot_mem1.burst : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.burst : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.burst : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.burst : '0);
    assign mem1_axi_arlock = (cpu_128b_ar_gnt_mem1 ? cpu_128b_ar_slot_mem1.lock : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.lock : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.lock : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.lock : '0);
    assign mem1_axi_arcache = (cpu_128b_ar_gnt_mem1 ? cpu_128b_ar_slot_mem1.cache : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.cache : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.cache : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.cache : '0);
    assign mem1_axi_arprot = (cpu_128b_ar_gnt_mem1 ? cpu_128b_ar_slot_mem1.prot : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.prot : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.prot : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.prot : '0);
    assign mem1_axi_arqos = (cpu_128b_ar_gnt_mem1 ? cpu_128b_ar_slot_mem1.qos : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.qos : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.qos : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.qos : '0);
    assign mem1_axi_arregion = (cpu_128b_ar_gnt_mem1 ? cpu_128b_ar_slot_mem1.region : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.region : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.region : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.region : '0);
    assign mem1_axi_aruser = (cpu_128b_ar_gnt_mem1 ? cpu_128b_ar_slot_mem1.user : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.user : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.user : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.user : '0);
    assign mem1_axi_arvalid = cpu_128b_ar_gnt_mem1 || dma_128b_ar_gnt_mem1 || acc_128b_ar_gnt_mem1 || io_128b_ar_gnt_mem1;

    // Rready (slave -> the master whose response arbiter granted it)
    assign mem1_axi_rready = (cpu_128b_r_rgnt_mem1 ? cpu_128b_rready : '0) |
        (dma_128b_r_rgnt_mem1 ? dma_128b_rready : '0) |
        (acc_128b_r_rgnt_mem1 ? acc_128b_rready : '0) |
        (io_128b_r_rgnt_mem1 ? io_128b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign mem1_axi_bridge_id_ar = (cpu_128b_ar_gnt_mem1 ? cpu_bridge_id_ar : '0) |
        (dma_128b_ar_gnt_mem1 ? dma_bridge_id_ar : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_bridge_id_ar : '0) |
        (io_128b_ar_gnt_mem1 ? io_bridge_id_ar : '0);


    // ================================================================
    // Slave 2: mem2 (32b)
    // ================================================================
    // Multi-master (4 masters) → mem2
    //   - cpu (rw)
    //   - dma (rw)
    //   - acc (rw)
    //   - io (rw)

    wire cpu_32b_aw_to_mem2 = ((cpu_32b_aw.addr >= 32'h30000000) && (cpu_32b_aw.addr <= 32'h3fffffff));
    wire cpu_32b_ar_to_mem2 = ((cpu_32b_ar.addr >= 32'h30000000) && (cpu_32b_ar.addr <= 32'h3fffffff));
    wire dma_32b_aw_to_mem2 = ((dma_32b_aw.addr >= 32'h30000000) && (dma_32b_aw.addr <= 32'h3fffffff));
    wire dma_32b_ar_to_mem2 = ((dma_32b_ar.addr >= 32'h30000000) && (dma_32b_ar.addr <= 32'h3fffffff));
    wire acc_32b_aw_to_mem2 = ((acc_32b_aw.addr >= 32'h30000000) && (acc_32b_aw.addr <= 32'h3fffffff));
    wire acc_32b_ar_to_mem2 = ((acc_32b_ar.addr >= 32'h30000000) && (acc_32b_ar.addr <= 32'h3fffffff));
    wire io_32b_aw_to_mem2 = ((io_32b_aw.addr >= 32'h30000000) && (io_32b_aw.addr <= 32'h3fffffff));
    wire io_32b_ar_to_mem2 = ((io_32b_ar.addr >= 32'h30000000) && (io_32b_ar.addr <= 32'h3fffffff));

    // AW request slots for mem2: arbitration at the slave pins
    assign cpu_32b_aw_slot_mem2_in_valid = cpu_32b_aw_to_mem2 && cpu_32b_awvalid && !cpu_32b_aw_hold_mem2;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_32b_aw_slot_mem2 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_32b_aw_slot_mem2_in_valid), .wr_ready(cpu_32b_aw_slot_mem2_in_ready), .wr_data(cpu_32b_aw),
        .rd_valid(cpu_32b_aw_slot_mem2_valid), .rd_ready(cpu_32b_aw_slot_mem2_ready), .rd_data(cpu_32b_aw_slot_mem2),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign dma_32b_aw_slot_mem2_in_valid = dma_32b_aw_to_mem2 && dma_32b_awvalid && !dma_32b_aw_hold_mem2;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_dma_32b_aw_slot_mem2 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_32b_aw_slot_mem2_in_valid), .wr_ready(dma_32b_aw_slot_mem2_in_ready), .wr_data(dma_32b_aw),
        .rd_valid(dma_32b_aw_slot_mem2_valid), .rd_ready(dma_32b_aw_slot_mem2_ready), .rd_data(dma_32b_aw_slot_mem2),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_32b_aw_slot_mem2_in_valid = acc_32b_aw_to_mem2 && acc_32b_awvalid && !acc_32b_aw_hold_mem2;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_acc_32b_aw_slot_mem2 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_32b_aw_slot_mem2_in_valid), .wr_ready(acc_32b_aw_slot_mem2_in_ready), .wr_data(acc_32b_aw),
        .rd_valid(acc_32b_aw_slot_mem2_valid), .rd_ready(acc_32b_aw_slot_mem2_ready), .rd_data(acc_32b_aw_slot_mem2),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_32b_aw_slot_mem2_in_valid = io_32b_aw_to_mem2 && io_32b_awvalid && !io_32b_aw_hold_mem2;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_io_32b_aw_slot_mem2 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_32b_aw_slot_mem2_in_valid), .wr_ready(io_32b_aw_slot_mem2_in_ready), .wr_data(io_32b_aw),
        .rd_valid(io_32b_aw_slot_mem2_valid), .rd_ready(io_32b_aw_slot_mem2_ready), .rd_data(io_32b_aw_slot_mem2),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for mem2: round-robin, lock until handshake ----
    logic [3:0] mem2_aw_arb_req;
    assign mem2_aw_arb_req = {io_32b_aw_slot_mem2_valid, acc_32b_aw_slot_mem2_valid, dma_32b_aw_slot_mem2_valid, cpu_32b_aw_slot_mem2_valid};
    logic [1:0] mem2_aw_arb_lock, mem2_aw_arb_rr;
    logic mem2_aw_arb_locked;
    wire [1:0] mem2_aw_arb_pick = (mem2_aw_arb_rr == 2'd0) ? (mem2_aw_arb_req[0] ? 2'd0 : mem2_aw_arb_req[1] ? 2'd1 : mem2_aw_arb_req[2] ? 2'd2 : 2'd3) : 
        (mem2_aw_arb_rr == 2'd1) ? (mem2_aw_arb_req[1] ? 2'd1 : mem2_aw_arb_req[2] ? 2'd2 : mem2_aw_arb_req[3] ? 2'd3 : 2'd0) : 
        (mem2_aw_arb_rr == 2'd2) ? (mem2_aw_arb_req[2] ? 2'd2 : mem2_aw_arb_req[3] ? 2'd3 : mem2_aw_arb_req[0] ? 2'd0 : 2'd1) : 
        mem2_aw_arb_req[3] ? 2'd3 : mem2_aw_arb_req[0] ? 2'd0 : mem2_aw_arb_req[1] ? 2'd1 : 2'd2;
    wire mem2_aw_arb_gnt_valid = mem2_aw_arb_locked || (|mem2_aw_arb_req);
    wire [1:0] mem2_aw_arb_gnt = mem2_aw_arb_locked ? mem2_aw_arb_lock : mem2_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem2_aw_arb_lock   <= '0;
            mem2_aw_arb_rr     <= '0;
            mem2_aw_arb_locked <= 1'b0;
        end else begin
            if (mem2_axi_awvalid && mem2_axi_awready) begin
                mem2_aw_arb_locked <= 1'b0;
                mem2_aw_arb_rr <= (mem2_aw_arb_gnt == 2'd3) ? 2'd0 : mem2_aw_arb_gnt + 1'b1;
            end else if (mem2_axi_awvalid) begin
                mem2_aw_arb_lock   <= mem2_aw_arb_gnt;
                mem2_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_32b_aw_gnt_mem2 = mem2_aw_arb_gnt_valid && (mem2_aw_arb_gnt == 2'd0) && mem2_aw_arb_req[0];
    wire dma_32b_aw_gnt_mem2 = mem2_aw_arb_gnt_valid && (mem2_aw_arb_gnt == 2'd1) && mem2_aw_arb_req[1];
    wire acc_32b_aw_gnt_mem2 = mem2_aw_arb_gnt_valid && (mem2_aw_arb_gnt == 2'd2) && mem2_aw_arb_req[2];
    wire io_32b_aw_gnt_mem2 = mem2_aw_arb_gnt_valid && (mem2_aw_arb_gnt == 2'd3) && mem2_aw_arb_req[3];
    assign cpu_32b_aw_slot_mem2_ready = cpu_32b_aw_gnt_mem2 && mem2_axi_awready;
    assign dma_32b_aw_slot_mem2_ready = dma_32b_aw_gnt_mem2 && mem2_axi_awready;
    assign acc_32b_aw_slot_mem2_ready = acc_32b_aw_gnt_mem2 && mem2_axi_awready;
    assign io_32b_aw_slot_mem2_ready = io_32b_aw_gnt_mem2 && mem2_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign mem2_axi_awid = (cpu_32b_aw_gnt_mem2 ? cpu_32b_aw_slot_mem2.id : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_32b_aw_slot_mem2.id : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_32b_aw_slot_mem2.id : '0) |
        (io_32b_aw_gnt_mem2 ? io_32b_aw_slot_mem2.id : '0);
    assign mem2_axi_awaddr = (cpu_32b_aw_gnt_mem2 ? cpu_32b_aw_slot_mem2.addr : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_32b_aw_slot_mem2.addr : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_32b_aw_slot_mem2.addr : '0) |
        (io_32b_aw_gnt_mem2 ? io_32b_aw_slot_mem2.addr : '0);
    assign mem2_axi_awlen = (cpu_32b_aw_gnt_mem2 ? cpu_32b_aw_slot_mem2.len : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_32b_aw_slot_mem2.len : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_32b_aw_slot_mem2.len : '0) |
        (io_32b_aw_gnt_mem2 ? io_32b_aw_slot_mem2.len : '0);
    assign mem2_axi_awsize = (cpu_32b_aw_gnt_mem2 ? cpu_32b_aw_slot_mem2.size : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_32b_aw_slot_mem2.size : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_32b_aw_slot_mem2.size : '0) |
        (io_32b_aw_gnt_mem2 ? io_32b_aw_slot_mem2.size : '0);
    assign mem2_axi_awburst = (cpu_32b_aw_gnt_mem2 ? cpu_32b_aw_slot_mem2.burst : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_32b_aw_slot_mem2.burst : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_32b_aw_slot_mem2.burst : '0) |
        (io_32b_aw_gnt_mem2 ? io_32b_aw_slot_mem2.burst : '0);
    assign mem2_axi_awlock = (cpu_32b_aw_gnt_mem2 ? cpu_32b_aw_slot_mem2.lock : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_32b_aw_slot_mem2.lock : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_32b_aw_slot_mem2.lock : '0) |
        (io_32b_aw_gnt_mem2 ? io_32b_aw_slot_mem2.lock : '0);
    assign mem2_axi_awcache = (cpu_32b_aw_gnt_mem2 ? cpu_32b_aw_slot_mem2.cache : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_32b_aw_slot_mem2.cache : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_32b_aw_slot_mem2.cache : '0) |
        (io_32b_aw_gnt_mem2 ? io_32b_aw_slot_mem2.cache : '0);
    assign mem2_axi_awprot = (cpu_32b_aw_gnt_mem2 ? cpu_32b_aw_slot_mem2.prot : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_32b_aw_slot_mem2.prot : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_32b_aw_slot_mem2.prot : '0) |
        (io_32b_aw_gnt_mem2 ? io_32b_aw_slot_mem2.prot : '0);
    assign mem2_axi_awqos = (cpu_32b_aw_gnt_mem2 ? cpu_32b_aw_slot_mem2.qos : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_32b_aw_slot_mem2.qos : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_32b_aw_slot_mem2.qos : '0) |
        (io_32b_aw_gnt_mem2 ? io_32b_aw_slot_mem2.qos : '0);
    assign mem2_axi_awregion = (cpu_32b_aw_gnt_mem2 ? cpu_32b_aw_slot_mem2.region : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_32b_aw_slot_mem2.region : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_32b_aw_slot_mem2.region : '0) |
        (io_32b_aw_gnt_mem2 ? io_32b_aw_slot_mem2.region : '0);
    assign mem2_axi_awuser = (cpu_32b_aw_gnt_mem2 ? cpu_32b_aw_slot_mem2.user : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_32b_aw_slot_mem2.user : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_32b_aw_slot_mem2.user : '0) |
        (io_32b_aw_gnt_mem2 ? io_32b_aw_slot_mem2.user : '0);
    assign mem2_axi_awvalid = cpu_32b_aw_gnt_mem2 || dma_32b_aw_gnt_mem2 || acc_32b_aw_gnt_mem2 || io_32b_aw_gnt_mem2;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [1:0] mem2_wowner_mem [16];
    logic [4:0] mem2_wowner_wptr, mem2_wowner_rptr;
    logic mem2_wowner_ahead;
    wire mem2_wowner_valid = (mem2_wowner_wptr != mem2_wowner_rptr);
    wire mem2_wowner_byp = !mem2_wowner_valid && !mem2_wowner_ahead && mem2_axi_awvalid;
    wire mem2_wowner_aw_hs = mem2_axi_awvalid && mem2_axi_awready;
    wire mem2_wowner_w_end = mem2_axi_wvalid && mem2_axi_wready && mem2_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem2_wowner_wptr  <= '0;
            mem2_wowner_rptr  <= '0;
            mem2_wowner_ahead <= 1'b0;
        end else begin
            if (mem2_wowner_aw_hs && mem2_wowner_ahead) begin
                mem2_wowner_ahead <= 1'b0;   // its W already went
            end else if (mem2_wowner_aw_hs && !(mem2_wowner_byp && mem2_wowner_w_end)) begin
                mem2_wowner_mem[mem2_wowner_wptr[3:0]] <= mem2_aw_arb_gnt;
                mem2_wowner_wptr <= mem2_wowner_wptr + 1'b1;
            end else if (!mem2_wowner_aw_hs && mem2_wowner_byp && mem2_wowner_w_end) begin
                mem2_wowner_ahead <= 1'b1;
            end
            if (mem2_wowner_valid && mem2_wowner_w_end) begin
                mem2_wowner_rptr <= mem2_wowner_rptr + 1'b1;
            end
        end
    )
    wire [1:0] mem2_wowner_head = mem2_wowner_valid ? mem2_wowner_mem[mem2_wowner_rptr[3:0]]
                                       : mem2_aw_arb_gnt;
    assign cpu_32b_w_sel_mem2 = (mem2_wowner_valid || mem2_wowner_byp) && (mem2_wowner_head == 2'd0) && cpu_32b_w_to_mem2;
    assign dma_32b_w_sel_mem2 = (mem2_wowner_valid || mem2_wowner_byp) && (mem2_wowner_head == 2'd1) && dma_32b_w_to_mem2;
    assign acc_32b_w_sel_mem2 = (mem2_wowner_valid || mem2_wowner_byp) && (mem2_wowner_head == 2'd2) && acc_32b_w_to_mem2;
    assign io_32b_w_sel_mem2 = (mem2_wowner_valid || mem2_wowner_byp) && (mem2_wowner_head == 2'd3) && io_32b_w_to_mem2;

    // W channel (owner-gated mux across writing masters)
    assign mem2_axi_wdata = ((cpu_32b_w_sel_mem2 && cpu_32b_wvalid) ? cpu_32b_w.data : '0) |
        ((dma_32b_w_sel_mem2 && dma_32b_wvalid) ? dma_32b_w.data : '0) |
        ((acc_32b_w_sel_mem2 && acc_32b_wvalid) ? acc_32b_w.data : '0) |
        ((io_32b_w_sel_mem2 && io_32b_wvalid) ? io_32b_w.data : '0);
    assign mem2_axi_wstrb = ((cpu_32b_w_sel_mem2 && cpu_32b_wvalid) ? cpu_32b_w.strb : '0) |
        ((dma_32b_w_sel_mem2 && dma_32b_wvalid) ? dma_32b_w.strb : '0) |
        ((acc_32b_w_sel_mem2 && acc_32b_wvalid) ? acc_32b_w.strb : '0) |
        ((io_32b_w_sel_mem2 && io_32b_wvalid) ? io_32b_w.strb : '0);
    assign mem2_axi_wlast = ((cpu_32b_w_sel_mem2 && cpu_32b_wvalid) ? cpu_32b_w.last : '0) |
        ((dma_32b_w_sel_mem2 && dma_32b_wvalid) ? dma_32b_w.last : '0) |
        ((acc_32b_w_sel_mem2 && acc_32b_wvalid) ? acc_32b_w.last : '0) |
        ((io_32b_w_sel_mem2 && io_32b_wvalid) ? io_32b_w.last : '0);
    assign mem2_axi_wuser = ((cpu_32b_w_sel_mem2 && cpu_32b_wvalid) ? cpu_32b_w.user : '0) |
        ((dma_32b_w_sel_mem2 && dma_32b_wvalid) ? dma_32b_w.user : '0) |
        ((acc_32b_w_sel_mem2 && acc_32b_wvalid) ? acc_32b_w.user : '0) |
        ((io_32b_w_sel_mem2 && io_32b_wvalid) ? io_32b_w.user : '0);
    assign mem2_axi_wvalid = (cpu_32b_w_sel_mem2 && cpu_32b_wvalid) || (dma_32b_w_sel_mem2 && dma_32b_wvalid) || (acc_32b_w_sel_mem2 && acc_32b_wvalid) || (io_32b_w_sel_mem2 && io_32b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign mem2_axi_bready = (cpu_32b_b_rgnt_mem2 ? cpu_32b_bready : '0) |
        (dma_32b_b_rgnt_mem2 ? dma_32b_bready : '0) |
        (acc_32b_b_rgnt_mem2 ? acc_32b_bready : '0) |
        (io_32b_b_rgnt_mem2 ? io_32b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign mem2_axi_bridge_id_aw = (cpu_32b_aw_gnt_mem2 ? cpu_bridge_id_aw : '0) |
        (dma_32b_aw_gnt_mem2 ? dma_bridge_id_aw : '0) |
        (acc_32b_aw_gnt_mem2 ? acc_bridge_id_aw : '0) |
        (io_32b_aw_gnt_mem2 ? io_bridge_id_aw : '0);

    // AR request slots for mem2: arbitration at the slave pins
    assign cpu_32b_ar_slot_mem2_in_valid = cpu_32b_ar_to_mem2 && cpu_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_32b_ar_slot_mem2 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_32b_ar_slot_mem2_in_valid), .wr_ready(cpu_32b_ar_slot_mem2_in_ready), .wr_data(cpu_32b_ar),
        .rd_valid(cpu_32b_ar_slot_mem2_valid), .rd_ready(cpu_32b_ar_slot_mem2_ready), .rd_data(cpu_32b_ar_slot_mem2),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign dma_32b_ar_slot_mem2_in_valid = dma_32b_ar_to_mem2 && dma_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_dma_32b_ar_slot_mem2 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_32b_ar_slot_mem2_in_valid), .wr_ready(dma_32b_ar_slot_mem2_in_ready), .wr_data(dma_32b_ar),
        .rd_valid(dma_32b_ar_slot_mem2_valid), .rd_ready(dma_32b_ar_slot_mem2_ready), .rd_data(dma_32b_ar_slot_mem2),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_32b_ar_slot_mem2_in_valid = acc_32b_ar_to_mem2 && acc_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_acc_32b_ar_slot_mem2 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_32b_ar_slot_mem2_in_valid), .wr_ready(acc_32b_ar_slot_mem2_in_ready), .wr_data(acc_32b_ar),
        .rd_valid(acc_32b_ar_slot_mem2_valid), .rd_ready(acc_32b_ar_slot_mem2_ready), .rd_data(acc_32b_ar_slot_mem2),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_32b_ar_slot_mem2_in_valid = io_32b_ar_to_mem2 && io_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_io_32b_ar_slot_mem2 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_32b_ar_slot_mem2_in_valid), .wr_ready(io_32b_ar_slot_mem2_in_ready), .wr_data(io_32b_ar),
        .rd_valid(io_32b_ar_slot_mem2_valid), .rd_ready(io_32b_ar_slot_mem2_ready), .rd_data(io_32b_ar_slot_mem2),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for mem2: round-robin, lock until handshake ----
    logic [3:0] mem2_ar_arb_req;
    assign mem2_ar_arb_req = {io_32b_ar_slot_mem2_valid, acc_32b_ar_slot_mem2_valid, dma_32b_ar_slot_mem2_valid, cpu_32b_ar_slot_mem2_valid};
    logic [1:0] mem2_ar_arb_lock, mem2_ar_arb_rr;
