        .rd_valid(acc_128b_aw_slot_subtractive_valid), .rd_ready(acc_128b_aw_slot_subtractive_ready), .rd_data(acc_128b_aw_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
